// ═══ PREVENTION 1: tryLock with timeout ═══
ReentrantLock lockA = new ReentrantLock();
ReentrantLock lockB = new ReentrantLock();

boolean transferWithRetry(Account from, Account to, BigDecimal amount) {
    while (true) {
        boolean gotA = false, gotB = false;
        try {
            gotA = lockA.tryLock(100, TimeUnit.MILLISECONDS);
            gotB = lockB.tryLock(100, TimeUnit.MILLISECONDS);
            if (gotA && gotB) {
                from.debit(amount);
                to.credit(amount);
                return true;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            if (gotB) lockB.unlock();
            if (gotA) lockA.unlock();
        }
        // Didn't get both locks → sleep briefly → retry
        Thread.sleep(ThreadLocalRandom.current().nextInt(50));
    }
}

// ═══ PREVENTION 2: ReadWriteLock (reduce contention) ═══
ReadWriteLock rwLock = new ReentrantReadWriteLock();

BigDecimal getBalance() {
    rwLock.readLock().lock();  // MULTIPLE readers concurrently!
    try { return balance; }
    finally { rwLock.readLock().unlock(); }
}

void debit(BigDecimal amount) {
    rwLock.writeLock().lock();  // EXCLUSIVE — blocks all readers and writers!
    try { balance = balance.subtract(amount); }
    finally { rwLock.writeLock().unlock(); }
}
// 100 threads reading balance: ALL concurrent! (readLock allows multiple)
// 1 thread debiting: exclusive. But only blocks for the debit duration.
