// ─── File: src/test/java/com/bank/detect/DeadlockDetectionTest.java ───
package com.bank.detect;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class DeadlockDetectionTest {

    // ═══ Programmatic deadlock detection ═══
    @Test
    void detectDeadlock_noDeadlockPresent() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        long[] deadlocked = tmx.findDeadlockedThreads();
        assertThat(deadlocked).isNull();  // no deadlock!
    }

    // ═══ tryLock with timeout — prevents deadlock ═══
    @Test
    void tryLock_preventsDeadlock() throws InterruptedException {
        ReentrantLock lockA = new ReentrantLock();
        ReentrantLock lockB = new ReentrantLock();
        int[] successCount = {0};
        int threads = 20;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            final boolean reverseOrder = i % 2 == 0;
            new Thread(() -> {
                ReentrantLock first = reverseOrder ? lockB : lockA;
                ReentrantLock second = reverseOrder ? lockA : lockB;
                try {
                    boolean gotFirst = first.tryLock(200, TimeUnit.MILLISECONDS);
                    if (gotFirst) {
                        try {
                            boolean gotSecond = second.tryLock(200, TimeUnit.MILLISECONDS);
                            if (gotSecond) {
                                try {
                                    synchronized (successCount) { successCount[0]++; }
                                } finally { second.unlock(); }
                            }
                        } finally { first.unlock(); }
                    }
                } catch (InterruptedException e) { }
                latch.countDown();
            }).start();
        }

        boolean completed = latch.await(10, TimeUnit.SECONDS);
        assertThat(completed).isTrue();  // ALL threads finished! No deadlock!
        assertThat(successCount[0]).isGreaterThan(0);
    }

    // ═══ ReadWriteLock — concurrent reads ═══
    @Test
    void readWriteLock_concurrentReads() throws InterruptedException {
        ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();
        int[] balance = {100000};
        int readers = 10;
        CountDownLatch allReading = new CountDownLatch(readers);
        CountDownLatch canFinish = new CountDownLatch(1);

        // 10 readers — ALL should be able to read simultaneously!
        for (int i = 0; i < readers; i++) {
            new Thread(() -> {
                rwLock.readLock().lock();
                try {
                    allReading.countDown();
                    try { canFinish.await(5, TimeUnit.SECONDS); } catch (InterruptedException e) { }
                    int b = balance[0];  // read
                } finally { rwLock.readLock().unlock(); }
            }).start();
        }

        // Wait until ALL 10 readers hold the read lock simultaneously
        boolean allHeldReadLock = allReading.await(5, TimeUnit.SECONDS);
        assertThat(allHeldReadLock).isTrue();  // all 10 reading concurrently!
        assertThat(rwLock.getReadLockCount()).isEqualTo(readers);

        canFinish.countDown();
        Thread.sleep(100);
    }

    // ═══ ReadWriteLock — writer exclusive ═══
    @Test
    void readWriteLock_writerExclusive() throws InterruptedException {
        ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();
        CountDownLatch writerHoldsLock = new CountDownLatch(1);

        Thread writer = new Thread(() -> {
            rwLock.writeLock().lock();
            try {
                writerHoldsLock.countDown();
                Thread.sleep(300);
            } catch (InterruptedException e) { }
            finally { rwLock.writeLock().unlock(); }
        });
        writer.start();
        writerHoldsLock.await();

        // Reader tries while writer holds lock → BLOCKED!
        long start = System.currentTimeMillis();
        rwLock.readLock().lock();
        try {
            long elapsed = System.currentTimeMillis() - start;
            assertThat(elapsed).isGreaterThanOrEqualTo(200);  // was blocked!
        } finally { rwLock.readLock().unlock(); }
        writer.join();
    }
}
